import 'package:flutter_secure_storage/flutter_secure_storage.dart';

class SecureStorageService {
  // 싱글톤 패턴
  static final SecureStorageService _instance = SecureStorageService._internal();
  factory SecureStorageService() => _instance;
  SecureStorageService._internal();

  // Android 옵션: EncryptedSharedPreferences 사용
  final _storage = const FlutterSecureStorage(
    aOptions: AndroidOptions(
      encryptedSharedPreferences: true,
    ),
    iOptions: IOSOptions(
      accessibility: KeychainAccessibility.first_unlock,
    ),
  );

  // 데이터 저장
  Future<void> write(String key, String value) async {
    await _storage.write(key: key, value: value);
  }

  // 데이터 읽기
  Future<String?> read(String key) async {
    return await _storage.read(key: key);
  }

  // 데이터 삭제
  Future<void> delete(String key) async {
    await _storage.delete(key: key);
  }

  // 모든 데이터 삭제
  Future<void> deleteAll() async {
    await _storage.deleteAll();
  }

  // 키 존재 여부 확인
  Future<bool> containsKey(String key) async {
    return await _storage.containsKey(key: key);
  }

  // 모든 데이터 읽기
  Future<Map<String, String>> readAll() async {
    return await _storage.readAll();
  }
}

// 사용 예시
void example() async {
  final storage = SecureStorageService();

  // 저장
  await storage.write('access_token', 'eyJhbGciOiJIUzI1NiIs...');
  await storage.write('refresh_token', 'dGhpcyBpcyBhIHJlZnJl...');

  // 읽기
  final token = await storage.read('access_token');
  print('Token: $token');

  // 삭제
  await storage.delete('access_token');

  // 전체 삭제 (로그아웃 시)
  await storage.deleteAll();
}

import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'dart:convert';

class AuthTokenService {
  static const _accessTokenKey = 'access_token';
  static const _refreshTokenKey = 'refresh_token';
  static const _tokenExpiryKey = 'token_expiry';
  static const _userDataKey = 'user_data';

  final _storage = const FlutterSecureStorage(
    aOptions: AndroidOptions(encryptedSharedPreferences: true),
  );

  // 토큰 저장
  Future<void> saveTokens({
    required String accessToken,
    required String refreshToken,
    required DateTime expiry,
  }) async {
    await Future.wait([
      _storage.write(key: _accessTokenKey, value: accessToken),
      _storage.write(key: _refreshTokenKey, value: refreshToken),
      _storage.write(key: _tokenExpiryKey, value: expiry.toIso8601String()),
    ]);
  }

  // 액세스 토큰 가져오기
  Future<String?> getAccessToken() async {
    final token = await _storage.read(key: _accessTokenKey);
    if (token == null) return null;

    // 만료 확인
    if (await isTokenExpired()) {
      return null; // 또는 리프레시 로직 호출
    }

    return token;
  }

  // 리프레시 토큰 가져오기
  Future<String?> getRefreshToken() async {
    return await _storage.read(key: _refreshTokenKey);
  }

  // 토큰 만료 확인
  Future<bool> isTokenExpired() async {
    final expiryStr = await _storage.read(key: _tokenExpiryKey);
    if (expiryStr == null) return true;

    final expiry = DateTime.parse(expiryStr);
    // 5분 전에 만료로 처리 (버퍼)
    return DateTime.now().isAfter(expiry.subtract(const Duration(minutes: 5)));
  }

  // 로그인 상태 확인
  Future<bool> isLoggedIn() async {
    final token = await getAccessToken();
    return token != null;
  }

  // 사용자 데이터 저장 (JSON)
  Future<void> saveUserData(Map<String, dynamic> userData) async {
    final jsonStr = jsonEncode(userData);
    await _storage.write(key: _userDataKey, value: jsonStr);
  }

  // 사용자 데이터 가져오기
  Future<Map<String, dynamic>?> getUserData() async {
    final jsonStr = await _storage.read(key: _userDataKey);
    if (jsonStr == null) return null;
    return jsonDecode(jsonStr) as Map<String, dynamic>;
  }

  // 로그아웃
  Future<void> logout() async {
    await _storage.deleteAll();
  }

  // 액세스 토큰만 갱신
  Future<void> updateAccessToken(String newToken, DateTime newExpiry) async {
    await Future.wait([
      _storage.write(key: _accessTokenKey, value: newToken),
      _storage.write(key: _tokenExpiryKey, value: newExpiry.toIso8601String()),
    ]);
  }
}

// HTTP 인터셉터에서 사용
class AuthInterceptor {
  final AuthTokenService _tokenService;

  AuthInterceptor(this._tokenService);

  Future<Map<String, String>> getAuthHeaders() async {
    final token = await _tokenService.getAccessToken();
    if (token == null) {
      throw Exception('No access token');
    }
    return {
      'Authorization': 'Bearer $token',
    };
  }
}

import 'package:flutter_secure_storage/flutter_secure_storage.dart';

class PlatformSecureStorage {
  // Android 옵션
  static AndroidOptions getAndroidOptions() {
    return const AndroidOptions(
      // EncryptedSharedPreferences 사용 (권장)
      encryptedSharedPreferences: true,
      // SharedPreferences 이름 (기본: FlutterSecureStorage)
      sharedPreferencesName: 'my_secure_prefs',
      // 키 접두사
      preferencesKeyPrefix: 'secure_',
      // 앱 재설치 시 데이터 유지 여부
      resetOnError: true,
    );
  }

  // iOS 옵션
  static IOSOptions getIOSOptions() {
    return const IOSOptions(
      // Keychain 접근성 (언제 접근 가능한지)
      // first_unlock: 첫 잠금 해제 후 접근 가능 (권장)
      // unlocked: 잠금 해제 상태에서만 접근 가능
      // passcode: 패스코드 설정된 경우만
      // first_unlock_this_device: 이 기기에서 첫 잠금 해제 후
      accessibility: KeychainAccessibility.first_unlock,
      // iCloud Keychain 동기화 여부
      synchronizable: false,
      // 앱 그룹 (앱 간 데이터 공유 시)
      // groupId: 'group.com.example.app',
      // 계정 이름
      accountName: 'com.example.app',
    );
  }

  // macOS 옵션
  static MacOsOptions getMacOSOptions() {
    return const MacOsOptions(
      accessibility: KeychainAccessibility.first_unlock,
      synchronizable: false,
      // useDataProtectionKeychain: true,
    );
  }

  // 플랫폼별 옵션이 적용된 스토리지
  static FlutterSecureStorage createStorage() {
    return FlutterSecureStorage(
      aOptions: getAndroidOptions(),
      iOptions: getIOSOptions(),
      mOptions: getMacOSOptions(),
    );
  }
}

// KeychainAccessibility 설명
enum KeychainAccessibilityExplained {
  // 기기 첫 잠금 해제 후 접근 가능 (앱이 백그라운드에서도 접근 가능)
  first_unlock,

  // 첫 잠금 해제 후 + 이 기기에서만 (iCloud 동기화 안됨)
  first_unlock_this_device,

  // 기기 잠금 해제 상태에서만 접근 가능
  unlocked,

  // 잠금 해제 + 이 기기에서만
  unlocked_this_device,

  // 패스코드가 설정된 경우만 접근 가능
  passcode,
}

import 'package:flutter/material.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'dart:convert';

// 인증 상태 관리
class AuthProvider extends ChangeNotifier {
  final _storage = const FlutterSecureStorage(
    aOptions: AndroidOptions(encryptedSharedPreferences: true),
  );

  bool _isLoggedIn = false;
  String? _userName;

  bool get isLoggedIn => _isLoggedIn;
  String? get userName => _userName;

  // 앱 시작 시 인증 상태 확인
  Future<void> checkAuthStatus() async {
    final token = await _storage.read(key: 'access_token');
    final userData = await _storage.read(key: 'user_data');

    if (token != null && userData != null) {
      _isLoggedIn = true;
      final user = jsonDecode(userData);
      _userName = user['name'];
    } else {
      _isLoggedIn = false;
      _userName = null;
    }
    notifyListeners();
  }

  // 로그인
  Future<void> login(String email, String password) async {
    // API 호출 (예시)
    // final response = await api.login(email, password);

    // 임시 데이터
    final response = {
      'access_token': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...',
      'refresh_token': 'refresh_token_here',
      'user': {'id': 1, 'name': '홍길동', 'email': email},
    };

    // 토큰 저장
    await _storage.write(
      key: 'access_token',
      value: response['access_token'] as String,
    );
    await _storage.write(
      key: 'refresh_token',
      value: response['refresh_token'] as String,
    );
    await _storage.write(
      key: 'user_data',
      value: jsonEncode(response['user']),
    );

    _isLoggedIn = true;
    _userName = (response['user'] as Map)['name'];
    notifyListeners();
  }

  // 로그아웃
  Future<void> logout() async {
    await _storage.deleteAll();
    _isLoggedIn = false;
    _userName = null;
    notifyListeners();
  }
}

// 앱 진입점
class MyApp extends StatelessWidget {
  final AuthProvider authProvider;

  const MyApp({super.key, required this.authProvider});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: AnimatedBuilder(
        animation: authProvider,
        builder: (context, _) {
          if (authProvider.isLoggedIn) {
            return HomeScreen(authProvider: authProvider);
          } else {
            return LoginScreen(authProvider: authProvider);
          }
        },
      ),
    );
  }
}

// 로그인 화면
class LoginScreen extends StatefulWidget {
  final AuthProvider authProvider;

  const LoginScreen({super.key, required this.authProvider});

  @override
  State<LoginScreen> createState() => _LoginScreenState();
}

class _LoginScreenState extends State<LoginScreen> {
  final _emailController = TextEditingController();
  final _passwordController = TextEditingController();
  bool _isLoading = false;

  Future<void> _login() async {
    setState(() => _isLoading = true);
    try {
      await widget.authProvider.login(
        _emailController.text,
        _passwordController.text,
      );
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('로그인 실패: $e')),
      );
    } finally {
      setState(() => _isLoading = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('로그인')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            TextField(
              controller: _emailController,
              decoration: const InputDecoration(labelText: '이메일'),
              keyboardType: TextInputType.emailAddress,
            ),
            const SizedBox(height: 16),
            TextField(
              controller: _passwordController,
              decoration: const InputDecoration(labelText: '비밀번호'),
              obscureText: true,
            ),
            const SizedBox(height: 24),
            SizedBox(
              width: double.infinity,
              child: ElevatedButton(
                onPressed: _isLoading ? null : _login,
                child: _isLoading
                    ? const CircularProgressIndicator()
                    : const Text('로그인'),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

// 홈 화면
class HomeScreen extends StatelessWidget {
  final AuthProvider authProvider;

  const HomeScreen({super.key, required this.authProvider});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('홈'),
        actions: [
          IconButton(
            icon: const Icon(Icons.logout),
            onPressed: () => authProvider.logout(),
          ),
        ],
      ),
      body: Center(
        child: Text('안녕하세요, ${authProvider.userName}님!'),
      ),
    );
  }
}
